const byId = new Map(QUESTION_BANK.map((q) => [q.id, q]));
const letter = (i) => String.fromCharCode(65 + i);

const scrollToTop = () => window.scrollTo({
  top: 0,
  behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "instant" : "smooth",
});

function ExamRunner({ exam, onExit }) {
  const questions = useMemo(
    () => exam.ids.map((id) => byId.get(id)).filter(Boolean),
    [exam]
  );

  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState({});
  const [finished, setFinished] = useState(false);
  const questionHeadingRef = useRef(null);
  const resultHeadingRef = useRef(null);

  useEffect(() => {
    const heading = finished ? resultHeadingRef.current : questionHeadingRef.current;
    heading?.focus({ preventScroll: true });
  }, [currentIndex, finished]);

  const current = questions[currentIndex];
  const selected = answers[currentIndex];
  const answered = selected !== undefined;
  const answeredCount = questions.filter((_, index) => answers[index] !== undefined).length;
  const unansweredCount = questions.length - answeredCount;

  const scoreableTotal = questions.filter((q) => q.a !== null && q.a !== undefined).length;
  const unscoredTotal = questions.length - scoreableTotal;

  const score = useMemo(
    () =>
      questions.reduce(
        (sum, q, i) =>
          sum + (q.a !== null && q.a !== undefined && answers[i] === q.a ? 1 : 0),
        0
      ),
    [answers, questions]
  );

  const percentage = scoreableTotal
    ? Math.round((score / scoreableTotal) * 100)
    : null;

  const choose = (index) =>
    setAnswers((prev) => ({ ...prev, [currentIndex]: index }));

  const previous = () => {
    if (currentIndex > 0) setCurrentIndex((i) => i - 1);
  };

  const next = () => {
    if (currentIndex === questions.length - 1) {
      setFinished(true);
      scrollToTop();
    } else {
      setCurrentIndex((i) => i + 1);
    }
  };

  const restart = () => {
    setCurrentIndex(0);
    setAnswers({});
    setFinished(false);
    scrollToTop();
  };

  const reviewQuestion = (index) => {
    setCurrentIndex(index);
    setFinished(false);
    scrollToTop();
  };

  if (!current && !finished) {
    return (
      <div className="empty-card">
        <h2>No questions available</h2>
        <button className="primary" onClick={onExit}>Back to Dashboard</button>
      </div>
    );
  }

  if (finished) {
    return (
      <div className="exam-shell">
        <header className="exam-header">
          <div>
            <p className="eyebrow">Exam completed</p>
            <h1>{exam.title}</h1>
            <p className="subtitle">{exam.subtitle}</p>
          </div>
          <button className="secondary top-exit" onClick={onExit}>Dashboard</button>
        </header>

        <section className="result-card">
          <div className="score-circle">
            <strong>{percentage === null ? "Study" : `${percentage}%`}</strong>
            <span>{percentage === null ? "Unscored" : "Final Score"}</span>
          </div>

          <div>
            <h2 ref={resultHeadingRef} tabIndex={-1}>{percentage === null ? "Study Session Complete" : "Your Result"}</h2>

            {percentage !== null ? (
              <>
                <p>Score: <strong>{score} / {scoreableTotal}</strong></p>
                <p>Percentage: <strong>{percentage}%</strong></p>
              </>
            ) : (
              <p>You’ve finished this study session. These questions don’t have an answer key, so they aren’t scored.</p>
            )}

            {unscoredTotal > 0 && (
              <p className="source-note">
                {unscoredTotal} question{unscoredTotal === 1 ? "" : "s"} are study-only because
                the uploaded source did not supply a correct answer.
              </p>
            )}
          </div>
        </section>

        <section className="stats stats-with-navigation" aria-label="Exam results">
          <div className="stat"><span>Total</span><strong>{questions.length}</strong></div>
          <div className="stat"><span>Answered</span><strong>{answeredCount}</strong></div>
          <div className="stat"><span>Unanswered</span><strong>{unansweredCount}</strong></div>
          <div className="stat"><span>Scored</span><strong>{scoreableTotal}</strong></div>
          <div className="stat"><span>Correct</span><strong className="green">{score}</strong></div>
          <div className="stat"><span>Study-only</span><strong>{unscoredTotal}</strong></div>
        </section>

        <section className="review-section">
          <div className="section-title-row">
            <div>
              <p className="eyebrow">Review mode</p>
              <h2>All Questions</h2>
            </div>
          </div>

          <div className="review-list">
            {questions.map((q, i) => {
              const ua = answers[i];
              const keyed = q.a !== null && q.a !== undefined;
              const correct = keyed && ua === q.a;
              const questionAnswered = ua !== undefined;

              return (
                <article
                  key={`${q.id}-${i}`}
                  className={`review-card ${
                    !questionAnswered ? "review-unanswered" : !keyed ? "review-study" : correct ? "review-correct" : "review-wrong"
                  }`}
                >
                  <div className="review-top">
                    <span>Question {i + 1} · {q.topic || "General"}</span>
                    <span
                      className={`status ${
                        !questionAnswered ? "unanswered-status" : !keyed ? "study-status" : correct ? "correct-status" : "wrong-status"
                      }`}
                    >
                      {!questionAnswered ? "Unanswered" : !keyed ? "Study-only" : correct ? "Correct" : "Incorrect"}
                    </span>
                  </div>

                  <h3>{q.q}</h3>

                  <div className="review-row">
                    <span>Your answer</span>
                    <strong>
                      {ua !== undefined ? `${letter(ua)}. ${q.o[ua]}` : "Not answered"}
                    </strong>
                  </div>

                  {keyed && (
                    <div className="review-row">
                      <span>Correct answer</span>
                      <strong>{letter(q.a)}. {q.o[q.a]}</strong>
                    </div>
                  )}

                  <p className="explanation">
                    <strong>{keyed ? "Explanation:" : "Source note:"}</strong> {q.e}
                  </p>

                  <p className="source-line">
                    Source: {q.source || "Previous platform"}
                    {q.session ? ` · ${q.session}` : ""}
                  </p>

                  <button className="text-button" onClick={() => reviewQuestion(i)}>
                    Review this question
                  </button>
                </article>
              );
            })}
          </div>
        </section>

        <button className="restart" onClick={restart}>Restart Exam</button>
      </div>
    );
  }

  const keyed = current.a !== null && current.a !== undefined;

  return (
    <div className="exam-shell exam-shell-active">
      <header className="exam-header">
        <div>
          <p className="eyebrow">{current.topic || "Interactive exam"}</p>
          <h1>{exam.title}</h1>
          <p className="subtitle">{exam.subtitle}</p>
        </div>
        <button className="secondary top-exit" onClick={onExit}>Dashboard</button>
      </header>

      <div className="exam-layout">
      <aside className="question-navigator" aria-labelledby="navigator-title">
        <div className="navigator-heading">
          <h2 id="navigator-title">Questions</h2>
          <span className="navigator-count">{answeredCount}/{questions.length}</span>
        </div>
        <p className="navigator-summary" role="status">{answeredCount} answered · {unansweredCount} unanswered</p>
        <nav className="question-number-grid" aria-label="Go to a question">
          {questions.map((question, index) => {
            const isAnswered = answers[index] !== undefined;
            const isCurrent = currentIndex === index;
            return (
              <button
                key={`${question.id}-${index}`}
                type="button"
                className={`question-number ${isAnswered ? "is-answered" : ""} ${isCurrent ? "is-current" : ""}`}
                aria-label={`Question ${index + 1}, ${isAnswered ? "answered" : "unanswered"}`}
                aria-current={isCurrent ? "step" : undefined}
                onClick={() => reviewQuestion(index)}
              >
                {index + 1}
              </button>
            );
          })}
        </nav>
        <div className="navigator-legend" aria-label="Question status legend">
          <span><span className="legend-dot is-answered" aria-hidden="true" />Answered</span>
          <span><span className="legend-dot" aria-hidden="true" />Unanswered</span>
        </div>
      </aside>
      <section className="question-card" aria-labelledby="current-question">
        <div className="question-meta">
          <span className="topic-chip">{current.topic || "General"}</span>
          {!keyed && <span className="study-chip">Source answer unavailable</span>}
        </div>

        <p className="qnum">Question {currentIndex + 1}</p>
        <h2 className="question-text" id="current-question" ref={questionHeadingRef} tabIndex={-1}>{current.q}</h2>

        <div className="answers" role="radiogroup" aria-labelledby="current-question">
          {current.o.map((option, i) => {
            const isSelected = selected === i;
            const isCorrect = keyed && i === current.a;

            let state = "";
            if (answered && keyed && isCorrect) state = "correct";
            else if (answered && keyed && isSelected && !isCorrect) state = "wrong";
            else if (answered && !keyed && isSelected) state = "study-selected";

            return (
              <label
                key={i}
                className={`answer ${state} ${isSelected ? "selected" : ""}`}
              >
                <input
                  type="radio"
                  name={`q-${currentIndex}`}
                  aria-label={`${letter(i)}. ${option}`}
                  checked={isSelected}
                  onChange={() => choose(i)}
                />
                <span className="option-letter">{letter(i)}</span>
                <span className="option-text">{option}</span>

                {answered && keyed && isCorrect && (
                  <span className="indicator correct-label">Correct</span>
                )}
                {answered && keyed && isSelected && !isCorrect && (
                  <span className="indicator wrong-label">Your answer</span>
                )}
                {answered && !keyed && isSelected && (
                  <span className="indicator study-label">Selected</span>
                )}
              </label>
            );
          })}
        </div>

        {answered && keyed && (
          <aside role="status" className={`feedback ${selected === current.a ? "feedback-good" : "feedback-bad"}`}>
            <h3>{selected === current.a ? "Correct answer." : "Incorrect answer."}</h3>
            <p>
              <strong>Correct answer:</strong> {letter(current.a)}. {current.o[current.a]}
            </p>
            {current.e && <p><strong>Explanation:</strong> {current.e}</p>}
          </aside>
        )}

        {answered && !keyed && (
          <aside className="feedback feedback-study" role="status">
            <h3>Answer saved.</h3>
            <p>
              This question is for revision. The source doesn’t include an answer key,
              so it won’t count toward your score.
            </p>
          </aside>
        )}

        {!answered && (
          <p></p> // <p className="hint">Choose an answer, or skip this question and return later.</p>
        )}

        <p className="source-line current-source">
          Source: {current.source || "Previous platform"}
          {current.session ? ` · ${current.session}` : ""}
        </p>

        <div className="nav">
          <button
            className="secondary"
            onClick={previous}
            disabled={currentIndex === 0}
          >
            Previous
          </button>
          <button className="primary" onClick={next}>
            {currentIndex === questions.length - 1 ? "Finish Exam" : "Next"}
          </button>
        </div>
      </section>
      </div>
    </div>
  );
}

export default function InterPrep() {
  return <InterPrepDashboard questionBank={QUESTION_BANK} exams={EXAMS} byId={byId} ExamRunner={ExamRunner} />;
}
